// Format error context for outbound notification
const errorData = $input.item.json;

const executionId = errorData.execution?.id || 'unknown-exec-id';
const workflowName = errorData.workflow?.name || 'unknown-workflow';
const workflowId = errorData.workflow?.id || 'unknown-workflow-id';
const errorMessage = errorData.execution?.error?.message || errorData.execution?.error?.description || 'Unhandled execution failure';
const timestamp = new Date().toISOString();

const formattedAlert = {
  alert_type: 'n8n_workflow_error',
  timestamp: timestamp,
  workflow: {
    id: workflowId,
    name: workflowName
  },
  execution: {
    id: executionId,
    error: errorMessage
  },
  summary: `[ALERT] Workflow "${workflowName}" failed during execution ${executionId}: ${errorMessage}`
};

return {
  json: {
    formattedAlert,
    executionId,
    workflowName,
    errorMessage,
    timestamp
  }
};
